from decimal import Decimal, ROUND_HALF_UP


def tax(amount, rate):
    """Tax on an invoice amount, rounded half up to the cent (FIN-12)."""
    tax_amount = Decimal(str(amount)) * Decimal(str(rate))
    return float(tax_amount.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))

from src.invoice import tax


def test_invoice_tax():
    # Finance policy FIN-12: tax is rounded half up to the cent.
    assert tax(112.50, 0.09) == 10.13


def test_invoice_tax_below_half_cent():
    assert tax(112.49, 0.09) == 10.12


def test_invoice_tax_above_half_cent():
    assert tax(112.51, 0.09) == 10.13


def test_invoice_tax_decimal_half_cent():
    # Binary floating-point multiplication must not affect a decimal tie.
    assert tax(1.005, 1) == 1.01


def test_invoice_tax_zero():
    assert tax(0, 0.09) == 0.0

